if(memberBackBtn){memberBackBtn.onclick=()=>{executeTransition(()=>{activeMemberFilter=null;sessionStorage.setItem("holokoyomi_active_member","");updateSidebarMemberStatus();memberProfileSubview.classList.add("u-hidden");membersListSubview.classList.remove("u-hidden");renderMembersList();});};}
