function restoreSavedState(){if(window.location.hash){try{history.replaceState(null,"",window.location.pathname+window.location.search);}catch(e){}}
localStorage.removeItem("holokoyomi_active_view");localStorage.removeItem("holokoyomi_active_member");const savedView=sessionStorage.getItem("holokoyomi_active_view")||"home";const savedMember=sessionStorage.getItem("holokoyomi_active_member");if(savedView==="members"&&savedMember&&fixedEvents[savedMember]){openMemberSpotlight(savedMember);}else if(savedMember&&fixedEvents[savedMember]&&savedView==="calendar"){activeMemberFilter=savedMember;updateSidebarMemberStatus();switchView("calendar");}else{switchView(savedView);}}
