const featuredEvents=getFeaturedEvents();const featuredDiff=featuredEvents[0]?.diffDays;if(todaySummaryLabel){if(featuredEvents.length===0){todaySummaryLabel.textContent="72時間以内の記念日・公式大型イベントはありません";}else if(featuredDiff===0){todaySummaryLabel.textContent=`きょうは ${featuredEvents.length} 件のイベントがあります！`;}else{const dayWord=featuredDiff===1?"あした":"あさって";todaySummaryLabel.textContent=`${dayWord}（${formatDisplayDate(featuredEvents[0].dateObj)}）に ${featuredEvents.length} 件のイベントがあります！`;}}
