function fireStageConfetti(stage,isManual=false){if(!stage)return;if(!isManual&&window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;const layer=stage.querySelector(".stage-confetti");if(!layer)return;const colors=["var(--stage-color)","var(--color-main)","var(--color-sub)","#FFD43B","#42B9EF","#B388FF"];const pieces=[];for(let i=0;i<70;i++){const fromLeft=i%2===0;const piece=document.createElement("i");piece.className=i%3===0?"confetti-piece _streamer":"confetti-piece";piece.style.setProperty("--c",colors[i%colors.length]);piece.style.setProperty("--x0",fromLeft?"3%":"97%");piece.style.setProperty("--dx",`${(fromLeft ? 1 : -1) * (60 + Math.random() * 380)}px`);piece.style.setProperty("--dy",`${-(160 + Math.random() * 240)}px`);piece.style.setProperty("--rot",`${Math.round(Math.random() * 1080 - 540)}deg`);piece.style.setProperty("--dur",`${1.8 + Math.random() * 1.2}s`);piece.style.setProperty("--delay",`${Math.random() * .25}s`);pieces.push(piece);}
layer.append(...pieces);stage.classList.remove("is-popping");void stage.offsetWidth;stage.classList.add("is-popping");setTimeout(()=>pieces.forEach(p=>p.remove()),3500);}
